import (
	"fmt"
	"runtime"
	"time"
)

// generateUUID creates a simple pseudo UUID for telemetry purposes, which changes on each process restart
func generateUUID() string {
	timestamp := time.Now().UnixNano()
	hash := fnv1a(fmt.Sprintf("%d%s", timestamp, runtime.NumCPU()))
	return fmt.Sprintf("%x", hash)
}

